import {
  Component,
  Element,
  h,
  Method,
  Prop,
  State,
  Event,
  EventEmitter,
  Host,
  ComponentInterface,
  JSX,
} from '@stencil/core';
import classnames from 'classnames';
import { ks } from '@fe-infra/keystone-design-tokens';
import { t } from '@src/shared/i18n';
import { Slot, type Slots } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { ToastVariant, ToastSize } from './types';
import { CSSProperties } from '@src/shared/dom';
import { createOpenCloseMotion } from '@src/shared/animation';
import { commonMessages } from '@fe-infra/keystone-locales';
import {
  KsIconClose,
  KsIconFilledCaution,
  KsIconFilledCheck,
  KsIconFilledInfo,
  KsIconFilledWarning,
  KsIconLoading,
} from '@fe-infra/keystone-icons-stencil';

const presetIcons: Record<ToastVariant, () => JSX.Element> = {
  success: () => <KsIconFilledCheck innerColor={ks.color.success.onFillLow} color={ks.color.success.fillLow} />,
  warning: () => <KsIconFilledWarning innerColor={ks.color.warning.onFillLow} color={ks.color.warning.fillLow} />,
  error: () => <KsIconFilledCaution innerColor={ks.color.error.onFillLow} color={ks.color.error.fillLow} />,
  info: () => <KsIconFilledInfo innerColor={ks.color.primary.onFillLow} color={ks.color.primary.fillLow} />,
  loading: () => <KsIconLoading color={ks.color.primary.fill} />,
};

const prefix = 'toast';

/**
 * @slot default - Slot for rich toast body content. Replaces the `message` slot and `message` prop when provided.
 * @slot icon - Slot for the icon displayed in the toast body.
 * @slot actions - Slot for action elements, displayed at the end of the toast.
 * @slot closeIcon - Slot for the content of the close button.
 * @slot message - Slot for the message of the toast.
 * @part base - The base container of the component.
 * @part icon - The icon element.
 * @part title - The title element.
 * @part message - The message content element.
 */
@Component({
  tag: 'ks-toast',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsToast implements ComponentInterface {
  @Element() el!: HTMLKsToastElement;
  private rootEl?: HTMLElement;
  private visibleAnimation = createOpenCloseMotion();
  @State() timer?: number;

  // props   --------------------
  /** The title of the global toast. This is the main heading of the toast. */
  @Prop() title = '';
  /** The message of the global toast. This provides additional information about the toast. */
  @Prop() message?: string;
  /** Indicates whether the icon should be displayed. When `true`, the icon will be shown. */
  @Prop() showIcon = true;
  /** The duration (in milliseconds) for which the toast will be displayed before automatically closing. If set to `0`, the toast will not close automatically. */
  @Prop() duration = 3000;
  /** Indicates whether the toast can be closed by the user. When `true`, the close button will be shown. */
  @Prop() closeable = false;
  /** The visual variant of the toast. Can be one of the following values: `"success"`, `"warning"`, `"error"`, `"info"` or `"loading"`. */
  @Prop() variant: ToastVariant = 'info';
  /** @deprecated Size is not editable anymore. The size of the toast. Can only be `"md"`. */
  @Prop() size: ToastSize = 'md';
  /** Pause auto close timer when hovering over toast content. */
  @Prop() pauseOnHover = false;
  /** The offset (in pixels) between the toast and the top of the container. */
  @Prop() topOffset?: number;
  /**
   *  @locale {en} The slot in the actions area, at the end of the toast.
   *  @locale {zh} actions 区域的插槽，在toast的末尾。
   */
  @Slot({ slotname: 'actions' }) private actionsSlots?: Slots;

  /** Custom styles applied to the toast component. This allows for additional styling beyond the default. */
  @Prop() popupStyle: CSSProperties;

  /** A lifecycle method that is called after the toast has opened. This can be used to perform any necessary actions after opening. */
  @Prop() afterOpen?: () => void | Promise<void>;
  /** A lifecycle method that is called after the toast has closed. This can be used to perform any necessary actions after closing. */
  @Prop() afterClose?: () => void | Promise<void>;

  // 外部事件 --------------------
  /** An event emitted when the toast is closed. This can be used to perform any necessary actions when the toast is closed. */
  @Event({ bubbles: false, composed: false }) ksClose?: EventEmitter;

  // 外部方法 --------------------
  /** A method that opens the toast. This can be used to display the toast to the user. */
  @Method()
  async open() {
    const completed = await this.visibleByAnime(true);
    if (!completed) {
      return;
    }
    this.afterOpen?.();
    this.autoClose();
    sendExposeTracking(this.el as HTMLElement, { eventType: 'popup' });
    sendDurationTracking(this.el as HTMLElement, { eventType: 'popup', reset: true });
  }
  /** A method that closes the toast. This can be used to hide the toast from the user. */
  @Method()
  async close() {
    await this.closeHandler();
  }

  constructor() {
    registerPluginManager(this.el as HTMLElement);
  }

  componentDidLoad(): void {
    this.open?.();
  }

  // 内部方法 --------------------
  private closeHandler = async () => {
    this.clearTimer();
    this.ksClose?.emit();
    const completed = await this.visibleByAnime(false);
    if (!completed) {
      return;
    }
    this.afterClose?.();
    sendDurationTracking(this.el as HTMLElement, { eventType: 'popup' });
  };

  private async visibleByAnime(val: boolean, isInit?: boolean) {
    const root = this.rootEl;
    if (!root) {
      return this.el.isConnected;
    }

    return this.visibleAnimation.translateFade(root, val, {
      duration: isInit ? 0 : 200,
      beforeOpen: () => root.setAttribute('style-show', 'true'),
      afterClose: () => root.removeAttribute('style-show'),
      checkConnected: true,
    });
  }

  private autoClose() {
    this.clearTimer();
    if (this.duration === 0) {
      return;
    }
    this.timer = window.setTimeout(async () => {
      await this.closeHandler();
      this.clearTimer();
    }, this.duration);
  }
  private clearTimer() {
    clearTimeout(this.timer);
    this.timer = undefined;
  }

  disconnectedCallback() {
    this.clearTimer();
    this.visibleAnimation.dispose();
  }

  // Simplified hover handlers: on enter, just clear timer; on leave, reset timer with full duration
  private onPointerEnter = () => {
    if (!this.pauseOnHover) return;
    this.clearTimer();
  };

  private onPointerLeave = () => {
    if (!this.pauseOnHover) return;
    // re-arm timer with full duration
    this.autoClose();
  };

  render() {
    const SIZE = 'md';
    const classes = classnames([`${prefix}`], [`${prefix}--${SIZE}`], [`${prefix}--${this.variant}`]);
    const role = ['warning', 'error'].includes(this.variant) ? 'alert' : 'status';

    return (
      <Host class="KsToast" role={role}>
        <div
          class={classes}
          part="base"
          ref={(el) => {
            this.rootEl = el;
          }}
          style={this.popupStyle}
          onPointerEnter={this.onPointerEnter}
          onPointerLeave={this.onPointerLeave}
          data-testid="ks-toast-index-pC6xCu"
        >
          <div class={`${prefix}__wrapper`}>
            {this.showIcon && (
              <span part="icon" class={classnames([`${prefix}__icon`, `${prefix}__icon--color-${this.variant}`])}>
                <slot name="icon">{presetIcons[this.variant]()}</slot>
              </span>
            )}
            <span class={`${prefix}__content`}>
              {this.title && (
                <div part="title" class={`${prefix}__title`}>
                  {this.title}
                </div>
              )}

              <div
                part="message"
                class={{
                  [`${prefix}__message`]: true,
                  [`${prefix}__message--with-icon`]: this.showIcon,
                }}
              >
                <slot>
                  <slot name="message">{this.message ?? t(commonMessages.empty)}</slot>
                </slot>
              </div>

              {this.actionsSlots && (
                <div class={`${prefix}__actions`}>
                  <slot name="actions"></slot>
                </div>
              )}
            </span>
          </div>
          {this.closeable && (
            <ks-icon-button
              variant="text"
              size="xs"
              class={`${prefix}__close`}
              onClick={this.closeHandler}
              data-testid="ks-toast-index-stN5J3"
            >
              <slot name="closeIcon">
                <KsIconClose class={`${prefix}__close__icon`} size={14} />
              </slot>
            </ks-icon-button>
          )}
        </div>
      </Host>
    );
  }
}
